/bin/zsh -lc "cat > src/orchestration/tools/registry.acceptance.test.ts <<'EOF'
import {ToolRegistry} from './registry.js';
import {setLogger} from '../../shared/logger.js';

const definition = {
  name: 'weather',
  description: 'Get weather',
  inputSchema: {
    type: 'object',
    properties: {location: {type: 'string'}, units: {type: 'string', enum: ['metric', 'imperial'], default: 'metric'}},
    required: ['location'],
  },
};

test('rejects invalid input without executing or exposing values and passes valid input unchanged', async () => {
  const registry = new ToolRegistry();
  const received: Record<string, unknown>[] = [];
  const logs: string[] = [];
  const record = (category: string, message: string, fields?: Record<string, unknown>): void => {
    logs.push(JSON.stringify({category, message, fields}));
  };
  setLogger({debug: record, info: record, warn: record, error: record});
  registry.register(definition, async input => {
    received.push(input);
    return 'forecast';
  });
  try {
    const missing = await registry.execute('weather', {});
    const wrongType = await registry.execute('weather', {location: 314159, identity: 'private-person-827'});
    const wrongEnum = await registry.execute('weather', {location: 'Berlin', units: 'invalid-units-827'});
    const valid = {location: 'Berlin', extra: 'kept'};
    const accepted = await registry.execute('weather', valid);
    expect({missing: missing.result, wrongType: wrongType.result, wrongEnum: wrongEnum.result}).toEqual({
      missing: expect.stringMatching(/location/i),
      wrongType: expect.stringMatching(/location.*string|string.*location/i),
      wrongEnum: expect.stringMatching(/units/i),
    });
    expect(missing.result).toMatch(/required/i);
    expect(wrongEnum.result).toMatch(/enum|allowed/i);
    expect(JSON.stringify({missing, wrongType, wrongEnum, logs})).not.toMatch(/314159|private-person-827|invalid-units-827/);
    expect(accepted).toEqual({result: 'forecast'});
    expect(received).toEqual([valid]);
    await expect(registry.execute('absent', {})).rejects.toThrow('Unknown tool: absent');
  } finally {
    setLogger();
  }
});

test('rejects an invalid static schema when registering its tool', () => {
  const registry = new ToolRegistry();
  expect(() => registry.register({...definition, inputSchema: {type: 'not-a-type'}}, async () => 'forecast')).toThrow(
    /weather/i
  );
});

test('validates each call against the current dynamic definition', async () => {
  const registry = new ToolRegistry();
  let required = 'location';
  const received: Record<string, unknown>[] = [];
  registry.register(
    () => ({...definition, inputSchema: {type: 'object', required: [required]}}),
    async input => {
      received.push(input);
      return 'forecast';
    }
  );
  const first = await registry.execute('weather', {location: 'Berlin'});
  required = 'city';
  const rejected = await registry.execute('weather', {location: 'Berlin'});
  const second = await registry.execute('weather', {city: 'Paris'});
  expect(rejected.result).toMatch(/city/i);
  expect(rejected.result).toMatch(/required/i);
  expect([first.result, second.result]).toEqual(['forecast', 'forecast']);
  expect(received).toEqual([{location: 'Berlin'}, {city: 'Paris'}]);
});
EOF
mkdir -p specs/hal-engine-tool-input-validation
cat > specs/hal-engine-tool-input-validation/spec.md <<'EOF'
# Tool input validation

| Field | Value |
| ----- | ----- |
| Issue | re-cinq/HALEngine#37 |
| Status | Draft |

The registry validates model-supplied tool input against the registered tool's JSON Schema.

## Contract

- Invalid input is returned as a readable tool result naming the failed property and constraint without exposing values in results or logs; the executor is not called. Valid input, including extra properties, passes to the executor unchanged, and unknown tool names still throw. ([validated by: rejects invalid input without executing or exposing values and passes valid input unchanged](../../src/orchestration/tools/registry.acceptance.test.ts#L15))
- An invalid static schema fails at registration with an error naming the tool. ([validated by: rejects an invalid static schema when registering its tool](../../src/orchestration/tools/registry.acceptance.test.ts#L51))
- A function-valued definition is validated against its current schema on each call. ([validated by: validates each call against the current dynamic definition](../../src/orchestration/tools/registry.acceptance.test.ts#L58))
EOF
cat > .lore/dod.md <<'EOF'
# Definition of Done

> "'`ToolRegistry.execute` looks a tool up, logs the input'"'s key names, and calls the executor
> without ever checking the declared "'`inputSchema` (`src/orchestration/tools/registry.ts`).

**Strategy: `direct`** — `ToolRegistry.register` and `execute` expose the actual registry boundary, so tests can exercise real definitions and executors directly.

## Done when these pass

- [ ] **rejects invalid input without executing or exposing values and passes valid input unchanged** — Required, type and enum failures return safe, useful results; accepted input passes through, and unknown tools still throw.
  `src/orchestration/tools/registry.acceptance.test.ts`
- [ ] **rejects an invalid static schema when registering its tool** — Invalid static schemas fail at registration and identify the tool.
  `src/orchestration/tools/registry.acceptance.test.ts`
- [ ] **validates each call against the current dynamic definition** — Dynamic definitions use the schema resolved for each call.
  `src/orchestration/tools/registry.acceptance.test.ts`

## Facets

- [ ] Compile static schemas at registration and validate required fields, types and enums before execution, returning safe diagnostic results.
- [ ] Resolve and cache dynamic schemas by object while preserving extra properties and input values without coercion or defaults.
- [ ] Verify static compilation happens once across ten executions and exercise a rejected call followed by a corrected retry through the tool loop.
- [ ] Update the specified documentation, contract, changelog, dependency and minor version; include the migration note in the PR.

## Out of scope

- Changing unknown-tool errors, validating tool output, authorization, execution retries or implementing tools.
EOF
